/**
 * One energy pool per NPC ship, shared by boost AND weapons (owner rule
 * 2026-11-13: "Ships turning, acceleration, weapons, everything is related to
 * the ship, regardless of pilot"). A player's pool is the kind's `energyMax`,
 * regenerated by `energyRegenRate` per tick, spent by boost (`BOOST_TICK_COST`)
 * and by every slot trigger (`resolveSlotEnergyCost`). The NPC's pool must
 * follow the same rules from the same numbers.
 */
import { describe, it, expect } from 'vitest';
import { HostileDroneBehaviour } from './HostileDroneBehaviour.js';
import type { AiEntity, AiWorldView } from '../contracts/IAiBehaviour.js';
import { getShipKind } from '../../shared-types/shipKinds.js';
import { resolveSlotEnergyCost } from '../combat/Energy.js';
import { boostOf } from './pilotTestKit.js';

function droneAt(x: number, y: number): AiEntity {
  return { id: 'd', x, y, vx: 0, vy: 0, angle: 0, angvel: 0 };
}
function view(tick: number, players: Array<{ id: string; x: number; y: number }> = []): AiWorldView {
  return { tick, dtSec: 1 / 60, players: players.map((p) => ({ ...p, vx: 0, vy: 0, alive: true })) } as AiWorldView;
}

describe('HostileDroneBehaviour — one energy pool for boost and weapons', () => {
  it('starts full at the kind energyMax, the same pool size a player of that kind gets', () => {
    const kind = getShipKind('fighter');
    const b = new HostileDroneBehaviour(kind);
    expect(b.getEnergy()).toBe(kind.energyMax ?? 100);
    expect(b.getEnergyFrac()).toBe(1);
  });

  it('a weapon spend drains the pool by exactly the slot cost; a short pool refuses and is untouched', () => {
    const kind = getShipKind('fighter');
    const cost = resolveSlotEnergyCost(kind);
    expect(cost).toBeGreaterThan(0);
    const b = new HostileDroneBehaviour(kind);
    const max = b.getEnergy();
    expect(b.trySpendEnergy(cost)).toBe(true);
    expect(b.getEnergy()).toBeCloseTo(max - cost, 9);
    // Drain to below one shot.
    while (b.trySpendEnergy(cost)) { /* fire until dry */ }
    const left = b.getEnergy();
    expect(left).toBeLessThan(cost);
    expect(b.trySpendEnergy(cost), 'refused when short').toBe(false);
    expect(b.getEnergy(), 'a refused shot spends nothing').toBe(left);
    expect(b.getEnergyFrac()).toBeCloseTo(left / max, 9);
  });

  it('regenerates by the kind energyRegenRate per tick and the gun resumes', () => {
    const kind = getShipKind('fighter');
    const cost = resolveSlotEnergyCost(kind);
    const regen = kind.energyRegenRate ?? 0.25;
    const b = new HostileDroneBehaviour(kind);
    while (b.trySpendEnergy(cost)) { /* dry */ }
    const e0 = b.getEnergy();
    b.tick(droneAt(0, 0), view(1));
    expect(b.getEnergy()).toBeCloseTo(e0 + regen, 9);
    let t = 2;
    while (!b.trySpendEnergy(cost)) b.tick(droneAt(0, 0), view(t++));
    expect(t - 1, 'ticks to afford one more shot').toBe(Math.ceil((cost - e0) / regen - 1e-9));
  });

  it('boost and guns draw on the SAME pool: an empty pool after weapons fire cannot boost', () => {
    const kind = getShipKind('fighter');
    const b = new HostileDroneBehaviour(kind);
    b.markHostile('p', 0);
    while (b.trySpendEnergy(resolveSlotEnergyCost(kind))) { /* guns empty the pool */ }
    // Pool now below one boost tick after regen? Drain the rest too.
    b.trySpendEnergy(b.getEnergy());
    // A far target would normally make it boost (see HostileDroneBehaviour.test.ts).
    const intent = b.tick(droneAt(0, 0), view(1, [{ id: 'p', x: 0, y: b.getFireRange() * 3 }]));
    // One tick of regen (0.25) is below BOOST_TICK_COST (1.0): no boost.
    expect(boostOf(intent)).toBe(false);
  });
});
